# 样式聊天
这是一款简单的模组，允许服务器管理员自定义聊天界面的外观！

它添加了 Minecraft 支持的[现代聊天格式](https://placeholders.pb4.eu/user/text-format/)，但许多聊天模组/插件会忽略此功能。

它还兼容任何使用[占位符 API](https://placeholders.pb4.eu/user/general/)的模组。

它还支持通过权限为每位玩家自定义样式（支持 LuckPerms 和 PlayerRoles）

*本模组仅适用于 Fabric 模组加载器及兼容环境！*

如有任何问题，欢迎在我的 [Discord](https://pb4.eu/discord) 上提问。

[也欢迎查看我的其他模组和项目，或许对你有所帮助！](https://pb4.eu)

![Example image](https://i.imgur.com/HPSMaS8.png)
![Example image2](https://i.imgur.com/mSWzIV4.png)


## 命令（及对应权限）：
- `/styledchat` - 主命令（`styledchat.main`，默认开放）
- `/styledchat reload` - 重新加载配置与样式（需要 `styledchat.reload`）
- `/styledchat set <player> <type> <value>` - 将指定玩家 `<player>` 的 `<type>` 样式设置为 `<value>`（需要 `styledchat.set`）
- `/styledchat get <player> <type>` - 查看指定玩家 `<player>` 的 `<type>` 样式（需要 `styledchat.get`）
- `/styledchat clear <player> <type>` - 清除指定玩家 `<player>` 的 `<type>` 样式（需要 `styledchat.clear`）

## 配置说明：
配置文件位于 `./config/styled-chat.json`。
[格式语法采用简化文本格式](https://placeholders.pb4.eu/user/text-format/)。
支持使用来自[占位符 API](https://placeholders.pb4.eu/user/general/)的占位符。
此外，每种消息类型都拥有若干专属局部变量。

```json5
{
  "CONFIG_VERSION_DONT_TOUCH_THIS": 3,
  "_comment": "在修改任何内容前，请参阅 https://github.com/Patbox/StyledChat#configuration",
  "text_formatting": {
    // 启用聊天中的链接解析
    "parse_links": true,
    // 启用 Markdown 语法
    "markdown": true,
    // 启用聊天中的传统 (&x) 代码支持（仅限玩家输入时）
    "legacy_formatting": false,
    // 启用来自其他模组的格式化（如果其他模组实现不当，可能会破坏 StyledChat 的效果）
    "formatting_from_other_mods": false
  },
  "chat_preview": {
    // 在聊天预览中发送完整消息（包含所有包裹它的格式标签）
    "send_full_message": false,
    // 要求必须开启聊天预览才能应用格式化，否则禁用
    "require_for_formatting": false
  },
  "auto_completion": {
    // 启用标签自动补全（例如 <red>, <rainbow>）
    "tags": false,
    // 启用标签别名自动补全（例如 <c>, <rb>）
    "tag_aliases": false,
    // 启用表情符号自动补全（例如 :pos:, :item:）
    "emoticons": false
  },
  // 默认样式设置
  "default": {
    // 显示名称（局部变量：${default}, ${name}）
    "display_name": "${default}",
    // 消息样式
    "message_formats": {
      // 聊天消息样式（局部变量：${player}, ${message}）
      "chat": "<${player}> ${message}",
      // 加入游戏消息（局部变量：${player}）
      "joined_the_game": "<yellow><lang:multiplayer.player.joined:'${player}'></yellow>",
      // 改名后加入游戏消息（局部变量：${player}, ${old_name}）
      "joined_after_name_change": "<yellow><lang:multiplayer.player.joined.renamed:'${player}':'${old_name}'></yellow>",
      // 首次加入游戏消息（局部变量：${player}）
      "joined_for_first_time": "<yellow><lang:multiplayer.player.joined:'${player}'></yellow>",
      // 玩家离开服务器（局部变量：${player}）
      "left_game": "<yellow><lang:multiplayer.player.left:'${player}'></yellow>",
      // 玩家死亡消息（局部变量：${player}, ${default_message}）
      "base_death": "${default_message}",
      // 完成进度任务（局部变量：${player}, ${advancement}）
      "advancement_task": "<lang:chat.type.advancement.task:'${player}':'${advancement}'>",
      // 完成进度挑战（局部变量：${player}, ${advancement}）
      "advancement_challenge": "<lang:chat.type.advancement.challenge:'${player}':'${advancement}'>",
      // 完成进度目标（局部变量：${player}, ${advancement}） 
      "advancement_goal": "<lang:chat.type.advancement.goal:'${player}':'${advancement}'>",
      // 队伍消息，仅发送者可见（局部变量：${team}, ${displayName}, ${message}）
      "sent_team_chat": "<lang:'chat.type.team.sent':'<hover\\:\\'<lang\\:chat.type.team.hover>\\'><suggest_command\\:\\'/teammsg \\'>${team}':'${displayName}':'${message}'>",
      // 队伍消息，仅队伍成员可见（局部变量：${team}, ${displayName}, ${message}）
      "received_team_chat": "<lang:'chat.type.team.text':'<hover\\:\\'<lang\\:chat.type.team.hover>\\'><suggest_command\\:\\'/teammsg \\'>${team}':'${displayName}':'${message}'>",
      // 私聊消息，发送者可见（局部变量：${receiver}, ${sender}, ${message}）
      "sent_private_message": "<gray><italic><lang:commands.message.display.outgoing:'${receiver}':'${message}'>",
      // 私聊消息，接收者可见（局部变量：${receiver}, ${sender}, ${message}）
      "received_private_message": "<gray><italic><lang:commands.message.display.incoming:'${sender}':'${message}'>",
      // /say 命令输出（局部变量：${player}, ${message}）
      "say_command": "[${player}] ${message}",
      // /me 命令输出（局部变量：${player}, ${message}）
      "me_command": "<lang:'chat.type.emote':'${player}':'${message}'>",
      // 宠物死亡消息（局部变量：${default_message}, ${pet}）
      "pet_death": "${default_message}"
    },
    // 链接样式（局部变量：${link}, ${url}）
    "link_style": "<underline><c:#7878ff>${link}",
    // 剧透样式（局部变量：${spoiler}）
    "spoiler_style": "<gray>${spoiler}",
    // 剧透样式使用的分隔符
    "spoiler_symbol": "▌",
    // 玩家可使用的格式化标签
    "formatting": {
      // "格式化标签": true/false
      "dark_red": true,
      "green": true,
      "underline": true,
      "dark_green": true,
      "black": true,
      "yellow": true,
      "bold": true,
      "italic": true,
      "dark_blue": true,
      "dark_purple": true,
      "gold": true,
      "red": true,
      "aqua": true,
      "gray": true,
      "light_purple": true,
      "blue": true,
      "white": true,
      "dark_aqua": true,
      "dark_gray": true,
      "spoiler": true,
      "strikethrough": true
    },
    // 玩家可用的表情符号列表（聊天中使用 :name:）。支持占位符
    "emoticons": {
      // "名称": "值"
      "potion": "🧪",
      "item": "[%player:equipment_slot mainhand%]",
      "trident": "🔱",
      "rod": "🎣",
      "shrug": "¯\\_(ツ)_/¯",
      "bow": "🏹",
      "bell": "🔔",
      "heart": "❤",
      "bucket": "🪣",
      "sword": "🗡",
      "shears": "✂",
      "pos": "%player:pos_x% %player:pos_y% %player:pos_z%",
      "fire": "🔥",
      "table": "(╯°□°）╯︵ ┻━┻",
      // 自 2.2.1+1.20.1 版本起，你也可以通过以下语法从文件导入表情符号。
      "$emojibase:builtin:joypixels": "${emoji}",
      // 值的格式与其他项相同，只是 ${emoji} 会被替换为读取到的表情符号（例如可用于应用字体）
      // 格式结构如下：$类型:来源:路径
      // 类型可以是 Emojibase.dev 简写的 "emojibase"、Unicode cldr-json 注释的 "cldr"，或与此文件相同的 "default"（不含导入项）
      // 来源指向存储类型，路径指向具体文件
      //     "builtin" 表示从模组内置的 json 文件中加载（"joypixels" 或 "emojibase"）
      //     "from_file" 表示从配置文件目录相对路径的文件中加载（例如 "emoji.json" 指向 "[服务器根目录]/config/emoji.json"）

    }
  },
  // 样式列表，按从上到下的顺序应用，需满足特定条件
  "styles": [
    {
      // 应用该样式所需的条件
      "require": {
        "type": "...",
        // 相关说明请见：https://github.com/Patbox/PredicateAPI/blob/master/BUILTIN.md
      },
      /* 其余字段与 "default" 相同，但所有字段均为完全可选 */
    }
  ]
}
```

## 聊天内格式设置
如果玩家拥有所需权限（`styledchat.format.[tag_name]`，其中 `[tagname]` 为文本解析器标签），则他们可以在聊天中使用简化文本标签。
此外，你可以在配置文件中启用 Markdown 和传统 (&X) 格式。


## 示例配置
```json 
{
  "CONFIG_VERSION_DONT_TOUCH_THIS": 3,
  "_comment": "在修改任何内容前，请参阅 https://github.com/Patbox/StyledChat#configuration",
  "text_formatting": {
    "legacy_formatting": true,
    "parse_links": true,
    "markdown": true,
    "formatting_from_other_mods": true
  },
  "chat_preview": {
    "send_full_message": false,
    "require_for_formatting": false
  },
  "auto_completion": {
    "tags": false,
    "tag_aliases": false,
    "emoticons": true
  },
  "default": {
    "display_name": "${vanillaDisplayName}",
    "message_formats": {
      "chat": "${player} <dark_gray>»</dark_gray> ${message}",
      "joined_the_game": "<gray>✚</gray> <color:#85ff8f><lang:multiplayer.player.joined:'${player}'>",
      "joined_after_name_change": "<gray>✚</gray> <color:#85ff8f><lang:multiplayer.player.joined.renamed:'${player}':'${old_name}'>",
      "joined_for_first_time": "<yellow><lang:multiplayer.player.joined:'${player}'></yellow>",
      "left_game": "<gray>☁</gray> <color:#ff8585><lang:multiplayer.player.left:'${player}'>",
      "base_death": "<gray>☠</gray> <color:#d1d1d1>${default_message}",
      "advancement_task": "<lang:chat.type.advancement.task:'${player}':'${advancement}'>",
      "advancement_challenge": "<lang:chat.type.advancement.challenge:'${player}':'${advancement}'>",
      "advancement_goal": "<lang:chat.type.advancement.goal:'${player}':'${advancement}'>",
      "sent_team_chat": "<lang:'chat.type.team.sent':'<hover\\:\\'<lang\\:chat.type.team.hover>\\'><suggest_command\\:\\'/teammsg \\'>${team}':'${displayName}':'${message}'>",
      "received_team_chat": "<lang:'chat.type.team.text':'<hover\\:\\'<lang\\:chat.type.team.hover>\\'><suggest_command\\:\\'/teammsg \\'>${team}':'${displayName}':'${message}'>",
      "sent_private_message": "<gray>[<green>PM</green> → ${receiver}] <dark_gray>»<reset> ${message}",
      "received_private_message": "<gray>[<green>PM</green> ← ${sender}] <dark_gray>»<reset> ${message}",
      "say_command": "<red>[${player}] ${message}",
      "me_command": "<green>* ${player} ${message}",
      "pet_death": "Oh no! ${default_message}"
    },
    "link_style": "<underline><blue>${link}",
    "spoiler_style": "<dark_gray>${spoiler}",
    "spoiler_symbol": "▌",
    "formatting": {
      "dark_red": true,
      "underline": true,
      "yellow": true,
      "italic": true,
      "dark_blue": true,
      "dark_purple": true,
      "gold": true,
      "red": true,
      "aqua": true,
      "gray": true,
      "light_purple": true,
      "white": true,
      "pos": true,
      "dark_gray": true,
      "spoiler": true,
      "strikethrough": true,
      "st": true,
      "b": true,
      "item": true,
      "green": true,
      "dark_green": true,
      "black": true,
      "i": true,
      "bold": true,
      "blue": true,
      "dark_aqua": true
    },
    "emoticons": {
      "potion": "🧪",
      "trident": "🔱",
      "rod": "🎣",
      "shrug": "¯\\_(ツ)_/¯",
      "bow": "🏹",
      "bell": "<yellow>🔔",
      "heart": "<red>❤",
      "bucket": "🪣",
      "sword": "🗡",
      "shears": "✂",
      "fire": "🔥",
      "table": "<rb>(╯°□°）╯︵ ┻━┻"
    }
  },
  "styles": [
    {
      "require": {
        "type": "permission",
        "permission": "group.admin",
        "operator": 4
      },
      "display_name": "<dark_gray>[<red>Admin</red>]</dark_gray> <c:#ffe8a3>${vanillaDisplayName}</c>",
      "message_formats": {
        "chat": "${player} <dark_gray>»</dark_gray> <orange>${message}",
        "base_death": ""
      },
      "formatting": {},
      "emoticons": {}
    },
    {
      "require": {
        "type": "permission",
        "permission": "group.default"
      },
      "display_name": "<dark_gray>[<aqua>Player</aqua>]</dark_gray> <dark_aqua>${vanillaDisplayName}</dark_aqua>",
      "message_formats": {},
      "formatting": {},
      "emoticons": {}
    },
    {
      "require": {
        "type": "permission",
        "permission": "group.vip",
        "operator": 3
      },
      "message_formats": {},
      "formatting": {},
      "emoticons": {
        "potato": "<rb>Potato"
      }
